"""The core's database layer: the declarative base, the engine and the session factory, and the
safety net of a read that must not fail what reads it (``read_or_nothing``).

Conventions of every table (they are declared here once, and written out in the migration):

* identifiers are UUIDs generated by the database (``gen_random_uuid()``), except the provider
  ids (a short text the application generates, see ``llm.models``) and the audit log's sequence
  number (a bigserial);
* every timestamp is ``timestamptz``: values read back are timezone-aware, in UTC. The ones that
  mean "when this row was created" default to ``clock_timestamp()`` rather than ``now()``:
  ``now()`` is frozen at the start of the transaction, so rows created one after the other in a
  request would share one time and lose their order;
* constraints and indexes have explicit names, from the naming convention below.
"""

import importlib
import logging
from collections.abc import Awaitable, Callable
from contextlib import AbstractAsyncContextManager
from datetime import datetime

from sqlalchemy import DateTime, MetaData, Text
from sqlalchemy.ext.asyncio import (
    AsyncEngine,
    AsyncSession,
    async_sessionmaker,
    create_async_engine,
)
from sqlalchemy.orm import DeclarativeBase

from domo_core.config import CoreSettings

logger = logging.getLogger(__name__)

NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}

# Every module that declares tables. A new one must be listed here: Alembic and the tests use it
# to see all the tables.
MODEL_MODULES = (
    "domo_core.accounts.models",
    "domo_core.accounts.passkey_models",
    "domo_core.setup_flow.models",
    "domo_core.llm.models",
    "domo_core.llm.spending_models",
    "domo_core.chat.models",
    "domo_core.audit.models",
    "domo_core.household.models",
    "domo_core.confirmations.models",
    "domo_core.notes.models",
    "domo_core.policy.models",
    "domo_core.texts.models",
    "domo_core.identity.models",
    "domo_core.proofs.models",
    "domo_core.devices.models",
    "domo_core.memory.models",
    "domo_core.plans.models",
    "domo_core.deliveries.models",
    "domo_core.household.nicknames",
    "domo_core.trust.models",
    "domo_core.madetools.models",
    "domo_core.toolsdb.spaces",
    "domo_core.outward.models",
    "domo_core.channels.voice.models",
    "domo_core.learning.models",
    "domo_core.people.models",
)

# What the application hands out to open a database session (``async with factory() as session``).
SessionFactory = Callable[[], AbstractAsyncContextManager[AsyncSession]]


class Base(DeclarativeBase):
    """The base of every ORM model of the core."""

    metadata = MetaData(naming_convention=NAMING_CONVENTION)
    # A plain ``str`` is ``text`` (no length limit), a ``datetime`` is always ``timestamptz``.
    type_annotation_map = {str: Text(), datetime: DateTime(timezone=True)}
    # Server-generated values (ids, timestamps) are fetched with the INSERT/UPDATE itself: in
    # async code an expired attribute cannot be loaded lazily.
    __mapper_args__ = {"eager_defaults": True}


def load_models() -> None:
    """Import every model module, so that ``Base.metadata`` describes all the tables."""
    for name in MODEL_MODULES:
        importlib.import_module(name)


async def read_or_nothing[T](
    session: AsyncSession, what: str, read: Callable[[], Awaitable[T]], nothing: T
) -> T:
    """What ``read`` gives, read in a savepoint of ``session``; ``nothing`` when it fails. It is
    the safety net of what a turn reads besides what it must have (what Domo knows, planned,
    what someone's word has been worth...): a read that fails never fails the turn. The error is
    logged by its kind alone, with ``what`` was read, and the savepoint keeps the session
    usable."""
    try:
        async with session.begin_nested():
            return await read()
    except Exception as error:
        logger.error("The %s could not be read (%s)", what, type(error).__name__)
        return nothing


def create_engine(settings: CoreSettings) -> AsyncEngine:
    """The async engine for the database ``settings`` points at (asyncpg, one pool)."""
    return create_async_engine(settings.database_url, pool_pre_ping=True)


def make_session_factory(engine: AsyncEngine) -> async_sessionmaker[AsyncSession]:
    """Sessions on ``engine``. Objects stay readable after a commit (``expire_on_commit=False``):
    async code cannot reload an expired attribute implicitly."""
    return async_sessionmaker(engine, expire_on_commit=False)
